theorem rawChainMap_preserves_lipschitz (f : C(X, Y)) {L : ℝ≥0}
    (hL : LipschitzWith L f) (n : ℕ) :
    rawLipschitzCarrier X n ≤ (rawLipschitzCarrier Y n).comap (rawChainMap f n)
